    /// </summary>
    /// <param name = "cancellationToken">
    /// A cancellation token that can be used to cancel the operation.
    /// </param>
    public async Task<bool> HasPending(CancellationToken cancellationToken = default)
    {
        var queryBuilder = QueryBuilder.Select("hasPending");
        return await QueryExecutor.ExecuteAsync<bool>(GraphQLClient, queryBuilder, cancellationToken);
    }

    /// <summary>
    /// A unique identifier for this LLM.
    /// </summary>
    /// <param name = "cancellationToken">
