    /// </summary>
    /// <param name = "content">
    /// The response content
    /// </param>
    /// <param name = "inputTokens">
    /// Uncached input tokens sent
    /// </param>
    /// <param name = "outputTokens">
    /// Tokens received from the model, including text and tool calls
    /// </param>
    /// <param name = "cachedTokenReads">
    /// Cached input tokens read
    /// </param>
    /// <param name = "cachedTokenWrites">
    /// Cached input tokens written
    /// </param>
    /// <param name = "totalTokens">
    /// Total tokens consumed by this response
    /// </param>
    public Llm WithResponse(LlmcontentBlockInput[] content, int? inputTokens = 0, int? outputTokens = 0, int? cachedTokenReads = 0, int? cachedTokenWrites = 0, int? totalTokens = 0)
    {
        var arguments = ImmutableList<Argument>.Empty;
        arguments = arguments.Add(new Argument("content", new ListValue(content.Select(v => new ObjectValue(v.ToKeyValuePairs()) as Value).ToList())));
        if (inputTokens is int inputTokens_)
        {
            arguments = arguments.Add(new Argument("inputTokens", new IntValue(inputTokens_)));
        }

        if (outputTokens is int outputTokens_)
        {
            arguments = arguments.Add(new Argument("outputTokens", new IntValue(outputTokens_)));
        }

        if (cachedTokenReads is int cachedTokenReads_)
        {
            arguments = arguments.Add(new Argument("cachedTokenReads", new IntValue(cachedTokenReads_)));
        }

        if (cachedTokenWrites is int cachedTokenWrites_)
        {
            arguments = arguments.Add(new Argument("cachedTokenWrites", new IntValue(cachedTokenWrites_)));
        }

        if (totalTokens is int totalTokens_)
        {
            arguments = arguments.Add(new Argument("totalTokens", new IntValue(totalTokens_)));
        }

        var queryBuilder = QueryBuilder.Select("withResponse", arguments);
        return new Llm(queryBuilder, GraphQLClient);
