/// <summary>
/// A content block within an LLM message.
/// </summary>
public struct LlmcontentBlockInput(LlmcontentBlockKind kind, string text, string callId, string toolName, Json arguments, bool errored, string signature) : IInputObject
{
    /// <summary>
    /// The kind of content block.
    /// </summary>
    public LlmcontentBlockKind Kind { get; } = kind;
    /// <summary>
    /// Text content (for TEXT, THINKING, or TOOL_RESULT kinds).
    /// </summary>
    public string Text { get; } = text;
    /// <summary>
    /// The unique ID of a tool call (for TOOL_CALL or TOOL_RESULT kinds).
    /// </summary>
    public string CallId { get; } = callId;
    /// <summary>
    /// The name of the tool to call (for TOOL_CALL kind).
    /// </summary>
    public string ToolName { get; } = toolName;
    /// <summary>
    /// The arguments to pass to the tool (for TOOL_CALL kind).
    /// </summary>
    public Json Arguments { get; } = arguments;
    /// <summary>
    /// Whether the tool call resulted in an error (for TOOL_RESULT kind).
    /// </summary>
    public bool Errored { get; } = errored;
    /// <summary>
    /// Provider-specific opaque data (e.g. Anthropic thinking signature).
    /// </summary>
    public string Signature { get; } = signature;

    /// <summary>
    /// Converts this input object to GraphQL key-value pairs.
    /// </summary>
    public List<KeyValuePair<string, Value>> ToKeyValuePairs()
    {
        var kvPairs = new List<KeyValuePair<string, Value>>();
        kvPairs.Add(new KeyValuePair<string, Value>("kind", new StringValue(Kind.ToString()) as Value));
        kvPairs.Add(new KeyValuePair<string, Value>("text", new StringValue(Text) as Value));
        kvPairs.Add(new KeyValuePair<string, Value>("callId", new StringValue(CallId) as Value));
        kvPairs.Add(new KeyValuePair<string, Value>("toolName", new StringValue(ToolName) as Value));
        kvPairs.Add(new KeyValuePair<string, Value>("arguments", new StringValue(Arguments.Value) as Value));
        kvPairs.Add(new KeyValuePair<string, Value>("errored", new BooleanValue(Errored) as Value));
        kvPairs.Add(new KeyValuePair<string, Value>("signature", new StringValue(Signature) as Value));
        return kvPairs;
    }
}

