    public async Task<string> Ref(CancellationToken cancellationToken = default)
    {
        var queryBuilder = QueryBuilder.Select("ref");
        return await QueryExecutor.ExecuteAsync<string>(GraphQLClient, queryBuilder, cancellationToken);
    }

    /// <summary>
    /// Returns this object as a Node.
    /// This is a local type conversion — no GraphQL call.
    /// </summary>
    public Node AsNode()
    {
        return new NodeWrapper(QueryBuilder, GraphQLClient);
    }
